-- =====================================================================
-- Remocao dos vinculos indevidos em DET_DEMONSTRATIVO_CTACTB
-- Tenant alvo: tenant_51809 (API 2)
--
-- Contexto: 1226 contas de PASSIVO (2.1.01.01.* e 2.1.01.02.* -
-- fornecedores) estao vinculadas ao grupo de ATIVO "1.1.2 Contas a
-- receber" do Balanco Patrimonial Externo, referencia 2025-12-01
-- (ID_DET_DEMONSTRATIVO_REFERENCIA = 5), todas com SINAL = -1.
-- Esses vinculos NAO existem no tenant_47255 (API 1).
--
-- Impacto atual: inflam o grupo Contas a receber em 4.377.266,99
--
-- O grupo tem 1735 vinculos na API 2; apos a remocao ficam 509,
-- alinhados com a API 1.
-- =====================================================================

-- ---------------------------------------------------------------------
-- PASSO 1 - CONFERENCIA (rode antes; deve retornar 1226)
-- ---------------------------------------------------------------------
SELECT COUNT(*) AS QTD_A_REMOVER
FROM DET_DEMONSTRATIVO_CTACTB
WHERE ID_DET_DEMONSTRATIVO_REFERENCIA = 5
  AND SINAL = -1
  AND PADRAO_CTACTB LIKE '2.1.01.0%'
  AND ID BETWEEN 45292 AND 46517;

-- ---------------------------------------------------------------------
-- PASSO 2 - BACKUP (nao pule)
-- ---------------------------------------------------------------------
CREATE TABLE DET_DEMONSTRATIVO_CTACTB_BKP_20260807 AS
SELECT *
FROM DET_DEMONSTRATIVO_CTACTB
WHERE ID_DET_DEMONSTRATIVO_REFERENCIA = 5
  AND SINAL = -1
  AND PADRAO_CTACTB LIKE '2.1.01.0%'
  AND ID BETWEEN 45292 AND 46517;

-- ---------------------------------------------------------------------
-- PASSO 3 - DELETE
-- As 4 condicoes sao redundantes de proposito: cada uma sozinha ja
-- delimita o bloco, juntas impedem que a query pegue qualquer linha
-- fora dele. Confira que afetou exatamente 1226 linhas.
-- ---------------------------------------------------------------------
START TRANSACTION;

DELETE FROM DET_DEMONSTRATIVO_CTACTB
WHERE ID_DET_DEMONSTRATIVO_REFERENCIA = 5
  AND SINAL = -1
  AND PADRAO_CTACTB LIKE '2.1.01.0%'
  AND ID BETWEEN 45292 AND 46517;

-- Se o numero de linhas afetadas for 1226:  COMMIT;
-- Caso contrario:                                  ROLLBACK;

-- ---------------------------------------------------------------------
-- PASSO 4 - VALIDACAO (apos o COMMIT)
-- ---------------------------------------------------------------------
-- 4a) deve retornar 0
SELECT COUNT(*) AS SOBRARAM
FROM DET_DEMONSTRATIVO_CTACTB
WHERE ID_DET_DEMONSTRATIVO_REFERENCIA = 5
  AND PADRAO_CTACTB LIKE '2.%';

-- 4b) deve retornar 509
SELECT COUNT(*) AS TOTAL_GRUPO_CONTAS_A_RECEBER
FROM DET_DEMONSTRATIVO_CTACTB
WHERE ID_DET_DEMONSTRATIVO_REFERENCIA = 5;fei

-- 4c) a conta de caixa reinserida deve continuar la, com SINAL = 1
SELECT ID, ID_DET_DEMONSTRATIVO_REFERENCIA, PADRAO_CTACTB, SINAL
FROM DET_DEMONSTRATIVO_CTACTB
WHERE PADRAO_CTACTB = '1.1.01.01.000001';


